def calc_equation(equations, values, queries):
    parent, weight = {}, {}            # weight[x] = x / parent[x]

    def find(x):
        if parent[x] != x:
            root = find(parent[x])
            weight[x] *= weight[parent[x]]   # now x / root
            parent[x] = root
        return parent[x]

    for (a, b), v in zip(equations, values):
        for x in (a, b):
            if x not in parent:
                parent[x], weight[x] = x, 1.0
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
            weight[ra] = v * weight[b] / weight[a]   # ra / rb

    res = []
    for a, b in queries:
        if a not in parent or b not in parent or find(a) != find(b):
            res.append(-1.0)
        else:
            res.append(weight[a] / weight[b])
    return res

