def find_redundant_connection(edges):
    graph = {}

    def connected(a, b):               # is there already a path a → b?
        seen, stack = {a}, [a]
        while stack:
            u = stack.pop()
            if u == b:
                return True
            for v in graph.get(u, ()):
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
        return False

    for a, b in edges:
        if connected(a, b):
            return [a, b]
        graph.setdefault(a, []).append(b)
        graph.setdefault(b, []).append(a)
    return []
